'use strict';
// Opt-in replacement for the public Kalender Ekonomi panel only.
// The iframe URL must be generated by Investing.com's official widget tool
// after the website owner accepts the provider's terms. No scraping or proxying.
const RELEASE='mm-investing-calendar-20261118-v1';
const SCRIPT_ID='mm-investing-calendar-script';
const STYLE_ID='mm-investing-calendar-style';

function approvedInvestingUrl(raw){
  if(typeof raw!=='string'||raw.length>4096)return null;
  let url;
  try{url=new URL(raw.trim());}catch{return null;}
  if(url.protocol!=='https:'||url.hostname!=='sslecal2.investing.com'||
     url.port||url.username||url.password||url.pathname!=='/'||url.hash||!url.search)return null;
  // Require the standard parameters present in officially generated iframe URLs.
  if(!url.searchParams.has('columns')||!url.searchParams.has('calType')||
     !url.searchParams.has('timeZone')||!url.searchParams.has('lang'))return null;
  return url.href;
}

const STYLE=`<style id="${STYLE_ID}">
body.mm-investing-calendar-on #app{background:#f7f8fc!important;color:#172334!important}
body.mm-investing-calendar-on .mm85-shell{background:#f7f8fc!important;color:#172334!important;max-width:none!important;width:100%!important;box-sizing:border-box!important;border:0!important;box-shadow:none!important;padding:0!important}
body.mm-investing-calendar-on .mm85-shell > :not(#mm-investing-calendar){display:none!important}
body:not(.mm-investing-calendar-on) #mm-investing-calendar{display:none!important}
body.mm-investing-calendar-on #mm-investing-calendar{display:block!important;box-sizing:border-box;width:min(100%,1180px);margin:18px auto 32px;padding:0 14px;font:inherit;color:#172334}
.mm-investing-calendar-head{display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:14px;margin-bottom:15px}
.mm-investing-calendar-head h1{font-size:clamp(21px,2.6vw,29px);font-weight:800;line-height:1.2;letter-spacing:-.035em;color:#172334;margin:0 0 7px}
.mm-investing-calendar-head p{font-size:13px;color:#667085;margin:0;line-height:1.65}
.mm-investing-calendar-badges{display:flex;gap:7px;flex-wrap:wrap;align-items:center}
.mm-investing-calendar-badges span{font-size:11px;line-height:1.4;font-weight:750;color:#995204;background:#fff5e7;border:1px solid #ffdba6;border-radius:999px;padding:5px 10px}
.mm-investing-calendar-badges span:first-child{color:#1f5b48;background:#eaf9f1;border-color:#c7ebd6}
.mm-investing-calendar-card{border:1px solid #e5e9f0;border-radius:16px;background:#fff;box-shadow:0 10px 30px rgba(22,33,48,.06);overflow:hidden}
.mm-investing-calendar-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:12px 15px;border-bottom:1px solid #edf0f4;background:#fff}
.mm-investing-calendar-bar strong{font-size:12px;font-weight:800;color:#2f3b4d}
.mm-investing-calendar-bar button{cursor:pointer;border:1px solid #dfe3eb;border-radius:9px;padding:7px 12px;background:#fff;font-size:12px;font-weight:700;color:#42526b}
.mm-investing-calendar-bar button:hover,.mm-investing-calendar-bar button:focus-visible{border-color:#e58b1c;color:#a95b00;outline-offset:2px}
.mm-investing-calendar-scroll{width:100%;max-width:100%;overflow-x:auto;overscroll-behavior-x:contain;background:#fff}
.mm-investing-calendar-scroll iframe{display:block;width:100%;min-width:650px;height:720px;border:0;background:#fff}
.mm-investing-calendar-foot{display:flex;justify-content:space-between;gap:8px 15px;flex-wrap:wrap;align-items:center;background:#fff;padding:13px 15px;border-top:1px solid #edf0f4;color:#667085;font-size:12px;line-height:1.6}
.mm-investing-calendar-foot a{color:#bb6300;font-weight:750;text-decoration:none}
.mm-investing-calendar-foot a:hover{text-decoration:underline}
.mm-investing-calendar-note{font-size:12px;color:#667085;line-height:1.7;margin:13px 2px 0}
@media(max-width:720px){body.mm-investing-calendar-on #mm-investing-calendar{padding:0 8px;margin:10px auto 22px}.mm-investing-calendar-scroll iframe{height:650px}.mm-investing-calendar-card{border-radius:12px}.mm-investing-calendar-head h1{font-size:22px}}
</style>`;

const CLIENT=String.raw`(function(){
'use strict';
const EMBED_URL=__MM_IFRAME_URL__;
const RELEASE='mm-investing-calendar-20261118-v1';
function isCalendar(){
 const active=document.querySelector('.navbtn.active[data-page="Kalender Ekonomi"],.navbtn.is-active[data-page="Kalender Ekonomi"],[data-page="Kalender Ekonomi"][aria-current="page"]');
 const label=document.getElementById('toplabel');
 return !!active || /^\/kalender-ekonomi(?:\/)?$/i.test(location.pathname) || !!(label&&/^kalender ekonomi$/i.test((label.textContent||'').trim()));
}
function createCalendar(){
 const section=document.createElement('section');section.id='mm-investing-calendar';section.setAttribute('aria-label','Kalender Ekonomi Investing.com');
 section.innerHTML='<div class="mm-investing-calendar-head"><div><h1>Kalender Ekonomi</h1><p>Pantau jadwal data ekonomi penting dan hasil rilis langsung.</p></div><div class="mm-investing-calendar-badges"><span>● Pembaruan otomatis</span><span>WIB · UTC+7</span><span>High Impact</span></div></div><div class="mm-investing-calendar-card"><div class="mm-investing-calendar-bar"><strong>KALENDER EKONOMI GLOBAL</strong><button type="button" id="mm-investing-calendar-reload" aria-label="Muat ulang kalender">↻ Muat ulang</button></div><div class="mm-investing-calendar-scroll"><iframe id="mm-investing-calendar-frame" title="Kalender Ekonomi Investing.com, waktu WIB dan dampak tinggi" loading="eager" referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="mm-investing-calendar-foot"><span>Data, jadwal, dan pembaruan disediakan Investing.com</span><a href="https://id.investing.com/economic-calendar/" target="_blank" rel="noopener noreferrer nofollow">Buka kalender lengkap di Investing.com ↗</a></div></div><p class="mm-investing-calendar-note">Tampilan pada ponsel dapat digeser ke samping. Filter dan zona waktu mengikuti konfigurasi widget resmi Investing.com; jadwal serta hasil rilis dapat berubah.</p>';
 const iframe=section.querySelector('iframe');iframe.src=EMBED_URL;
 section.querySelector('#mm-investing-calendar-reload').addEventListener('click',()=>{iframe.src=EMBED_URL;});
 return section;
}
let lastShell=null,pending=false;
function mount(){
 const active=isCalendar();const shell=active?document.querySelector('.mm85-shell'):null;
 document.body.classList.toggle('mm-investing-calendar-on',!!shell);
 if(!shell){lastShell=null;return;}
 if(shell===lastShell && shell.querySelector('#mm-investing-calendar'))return;
 if(!shell.querySelector('#mm-investing-calendar'))shell.prepend(createCalendar());
 lastShell=shell;
}
function queue(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;mount();});}
function start(){
 queue();
 document.addEventListener('click',event=>{if(event.target.closest&&event.target.closest('.navbtn,[data-page="Kalender Ekonomi"]'))queue();});
 const root=document.getElementById('app')||document.body;
 new MutationObserver(queue).observe(root,{childList:true,subtree:true});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();`;

function injectInvestingCalendar(html,rawUrl=process.env.MM_INVESTING_CALENDAR_URL){
  if(typeof html!=='string'||!/<\/head\s*>/i.test(html)||!/<\/body\s*>/i.test(html))return html;
  const url=approvedInvestingUrl(rawUrl);
  if(!url||html.includes('id="'+SCRIPT_ID+'"'))return html;
  const safe=JSON.stringify(url).replace(/</g,'\\u003c').replace(/>/g,'\\u003e');
  const script='<script id="'+SCRIPT_ID+'" data-release="'+RELEASE+'">'+CLIENT.replace('__MM_IFRAME_URL__',safe)+'</script>';
  return html.replace(/<\/head\s*>/i,STYLE+'</head>').replace(/<\/body\s*>/i,script+'</body>');
}
module.exports={RELEASE,approvedInvestingUrl,injectInvestingCalendar,STYLE,CLIENT};